import React, { useState, useEffect } from "react";
import { Link } from "react-router-dom";
import {
  FaArrowLeft,
  FaArrowRight,
  FaArrowRight as FaArrow,
} from "react-icons/fa";
import { bannerAPI } from "../../utils/api";
import "./BannerSlider.css";

const BannerSlider = () => {
  const [banners, setBanners] = useState([]);
  const [currentIndex, setCurrentIndex] = useState(0);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    fetchBanners();
  }, []);

  useEffect(() => {
    if (banners.length > 1) {
      const interval = setInterval(() => {
        setCurrentIndex((prevIndex) => (prevIndex + 1) % banners.length);
      }, 5000); // Auto-advance every 5 seconds

      return () => clearInterval(interval);
    }
  }, [banners.length]);

  const fetchBanners = async () => {
    try {
      setLoading(true);
      const response = await bannerAPI.getActive();
      setBanners(response.data.data || []);
    } catch (error) {
      console.error("Error fetching banners:", error);
    } finally {
      setLoading(false);
    }
  };

  const nextSlide = () => {
    setCurrentIndex((prevIndex) => (prevIndex + 1) % banners.length);
  };

  const prevSlide = () => {
    setCurrentIndex(
      (prevIndex) => (prevIndex - 1 + banners.length) % banners.length
    );
  };

  const goToSlide = (index) => {
    setCurrentIndex(index);
  };

  if (loading) {
    return (
      <div className="banner-slider">
        <div className="banner-slide">
          <div className="banner-content">
            <div className="loading-spinner">
              <div className="spinner"></div>
              <p>Loading banners...</p>
            </div>
          </div>
        </div>
      </div>
    );
  }

  if (banners.length === 0) {
    return null; // Don't render anything if no banners
  }

  const currentBanner = banners[currentIndex];

  return (
    <div className="banner-slider">
      <div className="banner-slide">
        <div className="banner-image">
          <img
            src={`http://localhost:5000${currentBanner.image}`}
            alt={currentBanner.title}
          />
        </div>
        <div className="banner-content">
          <div className="banner-text">
            <h1 className="banner-title">{currentBanner.title}</h1>
            <p className="banner-description">{currentBanner.description}</p>
            {currentBanner.buttonText && (
              <Link
                to={currentBanner.link || "/products"}
                className="btn btn-primary banner-btn"
              >
                {currentBanner.buttonText}
                <FaArrow />
              </Link>
            )}
          </div>
        </div>

        {/* Navigation arrows */}
        {banners.length > 1 && (
          <>
            <button className="banner-nav banner-prev" onClick={prevSlide}>
              <FaArrowLeft />
            </button>
            <button className="banner-nav banner-next" onClick={nextSlide}>
              <FaArrowRight />
            </button>
          </>
        )}

        {/* Dots indicator */}
        {banners.length > 1 && (
          <div className="banner-dots">
            {banners.map((_, index) => (
              <button
                key={index}
                className={`banner-dot ${
                  index === currentIndex ? "active" : ""
                }`}
                onClick={() => goToSlide(index)}
              />
            ))}
          </div>
        )}
      </div>
    </div>
  );
};

export default BannerSlider;
